from hdutils import parse_default_value  # noqa: E402, F401


def main(*, timeseries, iqr_factor=7.5, window_size=15):
    # entrypoint function for this component
    # ***** DO NOT EDIT LINES ABOVE *****

    if window_size == 0:
        anomaly_series = pd.Series(False, index=timeseries.index)
    else:
        abs_diff = abs(
            timeseries
            - timeseries.rolling(
                window=window_size, center=True, min_periods=1
            ).median()
        )

        iqr = abs_diff.quantile(0.75) - abs_diff.quantile(0.25)
        threshold = abs_diff.quantile(0.75) + iqr_factor * iqr
        anomaly_series = abs_diff >= threshold

    anomaly_name_series = pd.Series(index=timeseries.index, dtype=object)
    anomaly_name_series[anomaly_series] = "Ausreißer"
    anomaly_name_series.fillna("", inplace=True)

    return {
        "anomaly_series": anomaly_series,
        "anomaly_name_series": anomaly_name_series,
    }


# Testing
try:
    import pytest

    data_dir = os.path.dirname(__file__) + "/../../../data/"
except (ImportError, NameError):
    pass
else:

    def test_run_to_export_anomaly_series():

        import_path = data_dir + "temperatur_essen_manipulated.txt"
        export_path = data_dir + "temperatur_essen_outliers.txt"
        timeseries = pd.read_csv(import_path, sep=";", index_col=0)["value"]
        result = main(timeseries=timeseries)
        result["anomaly_series"].to_csv(export_path, sep=";")
        assert isinstance(result, dict)


